// ====== EDIT ME ======
return [{ json: {
  // mode: "mock"    = built-in FAKE inventory + sales (no Shopify token)
  //       "shopify" = live Admin API (Header Auth X-Shopify-Access-Token); structure only until you connect a store
  mode: "mock",
  // output: "files" = CSV under outputFolder (self-hosted); "sheet" = Google Sheet tabs Alerts / Summary
  output: "files",
  filesFolder: "/home/node/.n8n-files/low-stock-alerts",
  outputFolder: "/home/node/.n8n-files/low-stock-alerts",
  shopDomain: "your-store.myshopify.com",
  shopifyApiVersion: "2025-07",
  lookbackDaysShort: 7,
  lookbackDaysLong: 30,
  safetyDays: 14,          // days of cover to keep; reorder_point = ceil(avg_daily_30 * safetyDays) + lowStockExtraUnits
  lowStockExtraUnits: 0,   // optional buffer on top of reorder_point
  summaryLanguage: "en",     // en | zh  (rule-based summary; both languages always stored in Summary rows)
}}];

// FAKE ceramic / jewelry / print shop — invented products, no real store.
// Cover: OK, LOW, OUT, NO_SALES, bursty 7d vs 30d, inventory tracking off.
const variants = [
  { product_id: 'P1', variant_id: 'V11', product_title: 'Speckled Oatmeal Mug', variant_title: 'Default Title', sku: 'MUG-OAT-DFT', inventory_quantity: 48, sales_7d: 4, sales_30d: 18, inventory_tracked: true },
  { product_id: 'P1', variant_id: 'V12', product_title: 'Speckled Oatmeal Mug', variant_title: 'Blue rim', sku: 'MUG-OAT-BLU', inventory_quantity: 6, sales_7d: 9, sales_30d: 36, inventory_tracked: true },
  { product_id: 'P1', variant_id: 'V13', product_title: 'Speckled Oatmeal Mug', variant_title: 'Red rim', sku: 'MUG-OAT-RED', inventory_quantity: 0, sales_7d: 3, sales_30d: 12, inventory_tracked: true },
  { product_id: 'P2', variant_id: 'V21', product_title: 'Gold Hoop Earrings', variant_title: 'Small 20mm', sku: 'HOOP-GLD-S', inventory_quantity: 80, sales_7d: 0, sales_30d: 0, inventory_tracked: true },
  { product_id: 'P2', variant_id: 'V22', product_title: 'Gold Hoop Earrings', variant_title: 'Large 40mm', sku: 'HOOP-GLD-L', inventory_quantity: 2, sales_7d: 14, sales_30d: 28, inventory_tracked: true },
  { product_id: 'P3', variant_id: 'V31', product_title: 'Botanical Print Set', variant_title: 'A4', sku: 'PRT-BOT-A4', inventory_quantity: 0, sales_7d: 0, sales_30d: 0, inventory_tracked: true },
  { product_id: 'P3', variant_id: 'V32', product_title: 'Botanical Print Set', variant_title: 'A3', sku: 'PRT-BOT-A3', inventory_quantity: 22, sales_7d: 5, sales_30d: 20, inventory_tracked: true },
  { product_id: 'P4', variant_id: 'V41', product_title: 'Linen Tea Towel', variant_title: 'Stripe', sku: 'TOW-LIN-STR', inventory_quantity: null, sales_7d: 2, sales_30d: 8, inventory_tracked: false },
  { product_id: 'P4', variant_id: 'V42', product_title: 'Linen Tea Towel', variant_title: 'Solid sand', sku: 'TOW-LIN-SND', inventory_quantity: 1, sales_7d: 7, sales_30d: 21, inventory_tracked: true },
];
const cfg = $('Config').first().json;
return [{ json: { variants, _cfg: cfg, source: 'mock' } }];

const cfg = $('Config').first().json;
const query = `{ products(first: 50) { nodes { id title variants(first: 50) { nodes { id title sku inventoryQuantity inventoryItem { id tracked } } } } } }`;
return [{ json: { _cfg: cfg, gql: { query }, step: 'products' } }];

// After products reply is read, build an orders query for the long lookback window.
const cfg = $('Config').first().json;
const prev = $input.first().json;
const days = Number(cfg.lookbackDaysLong) || 30;
const since = new Date(Date.now() - days * 864e5).toISOString().slice(0, 10);
const query = `query { orders(first: 100, query: "created_at:>=${since} status:any", sortKey: CREATED_AT, reverse: true) { nodes { createdAt lineItems(first: 50) { nodes { quantity sku variant { id } name } } } } }`;
return [{ json: { ...prev, gql: { query }, step: 'orders' } }];

// Merge product inventory with order line-item sales into the same shape as mock.
const cfg = $('Config').first().json;
const shortD = Number(cfg.lookbackDaysShort) || 7;
const longD = Number(cfg.lookbackDaysLong) || 30;
const productsReply = $('Shopify products (GraphQL)').first().json || {};
const ordersReply = $input.first().json || {};
if (productsReply.error || productsReply.errors || ordersReply.error || ordersReply.errors) {
  const err = JSON.stringify(productsReply.error || productsReply.errors || ordersReply.error || ordersReply.errors).slice(0, 300);
  return [{ json: { variants: [], _cfg: cfg, source: 'shopify', shopify_error: err } }];
}
const products = productsReply.data?.products?.nodes || [];
const orders = (ordersReply.data?.orders?.nodes) || [];
const now = Date.now();
const sales = {}; // variantId -> {7,30}
for (const o of orders) {
  const ageDays = (now - new Date(o.createdAt).getTime()) / 864e5;
  for (const li of (o.lineItems?.nodes || [])) {
    const vid = li.variant?.id || ('sku:' + (li.sku || li.name || ''));
    if (!sales[vid]) sales[vid] = { s7: 0, s30: 0 };
    const q = Number(li.quantity) || 0;
    if (ageDays <= longD) sales[vid].s30 += q;
    if (ageDays <= shortD) sales[vid].s7 += q;
  }
}
const variants = [];
for (const p of products) {
  for (const v of (p.variants?.nodes || [])) {
    const s = sales[v.id] || { s7: 0, s30: 0 };
    variants.push({
      product_id: p.id, variant_id: v.id, product_title: p.title, variant_title: v.title,
      sku: v.sku || '', inventory_quantity: v.inventoryQuantity, sales_7d: s.s7, sales_30d: s.s30,
      inventory_tracked: v.inventoryItem?.tracked !== false,
    });
  }
}
return [{ json: { variants, _cfg: cfg, source: 'shopify', shopify_error: '' } }];

/**
 * Low Stock Alerts — pure rules/math (no LLM).
 * Input: { variants: [...], _cfg: config }
 * Each variant: product_title, variant_title, sku, inventory_quantity, sales_7d, sales_30d,
 *               inventory_tracked (bool, default true), product_id?, variant_id?
 */
function ceil(n) { return Math.ceil(n); }

function computeOne(v, cfg) {
  const tracked = v.inventory_tracked !== false && v.inventory_tracked !== 'false';
  const invRaw = v.inventory_quantity;
  const inv = invRaw === null || invRaw === undefined || invRaw === '' ? null : Number(invRaw);
  const s7 = Number(v.sales_7d) || 0;
  const s30 = Number(v.sales_30d) || 0;
  const safety = Number(cfg.safetyDays) || 14;
  const extra = Number(cfg.lowStockExtraUnits) || 0;
  const shortD = Number(cfg.lookbackDaysShort) || 7;
  const longD = Number(cfg.lookbackDaysLong) || 30;

  const avg7 = s7 / shortD;
  const avg30 = s30 / longD;
  // reorder_point = ceil(avg_daily_30 * safetyDays) + lowStockExtraUnits
  const reorder_point = ceil(avg30 * safety) + extra;
  const suggested_order_qty = inv === null ? null : Math.max(0, reorder_point - inv);
  let days_of_cover = '';
  if (!tracked || inv === null) days_of_cover = '';
  else if (avg30 <= 0) days_of_cover = inv > 0 ? '∞' : '0';
  else days_of_cover = String(Math.round((inv / avg30) * 10) / 10);

  let status;
  if (!tracked) status = 'NOT_TRACKED';
  else if (inv !== null && inv <= 0) status = 'OUT';
  else if (s7 === 0 && s30 === 0) status = 'NO_SALES';
  else if (inv !== null && inv <= reorder_point) status = 'LOW';
  else status = 'OK';

  return {
    product_title: v.product_title || '',
    variant_title: v.variant_title || '',
    sku: v.sku || '',
    product_id: v.product_id || '',
    variant_id: v.variant_id || '',
    inventory_tracked: tracked ? 'yes' : 'no',
    inventory_quantity: inv === null ? '' : inv,
    sales_7d: s7,
    sales_30d: s30,
    avg_daily_7: Math.round(avg7 * 1000) / 1000,
    avg_daily_30: Math.round(avg30 * 1000) / 1000,
    days_of_cover,
    safety_days: safety,
    reorder_point,
    suggested_order_qty: suggested_order_qty === null ? '' : suggested_order_qty,
    status,
  };
}

function buildSummary(rows, cfg) {
  const counts = { OK: 0, LOW: 0, OUT: 0, NO_SALES: 0, NOT_TRACKED: 0 };
  for (const r of rows) counts[r.status] = (counts[r.status] || 0) + 1;
  const reorder = rows
    .filter(r => r.status === 'OUT' || r.status === 'LOW')
    .sort((a, b) => (Number(b.suggested_order_qty) || 0) - (Number(a.suggested_order_qty) || 0));
  const top = reorder.slice(0, 5).map(r => {
    const name = `${r.product_title}${r.variant_title && r.variant_title !== 'Default Title' ? ' / ' + r.variant_title : ''}`;
    return `${name} (sku ${r.sku || '—'}): stock ${r.inventory_quantity}, suggest order ${r.suggested_order_qty}, status ${r.status}`;
  });
  const lang = (cfg.summaryLanguage || 'en').toLowerCase();
  let text_en =
    `Checked ${rows.length} variants. OUT=${counts.OUT}, LOW=${counts.LOW}, OK=${counts.OK}, NO_SALES=${counts.NO_SALES}, NOT_TRACKED=${counts.NOT_TRACKED}. ` +
    `Reorder point ≈ ceil(avg daily sales over ${cfg.lookbackDaysLong || 30}d × ${cfg.safetyDays || 14} safety days)` +
    (Number(cfg.lowStockExtraUnits) ? ` + ${cfg.lowStockExtraUnits} buffer units` : '') + '. ';
  if (top.length) text_en += 'Top to reorder: ' + top.join('; ') + '.';
  else text_en += 'Nothing needs reordering right now.';

  let text_zh =
    `共检查 ${rows.length} 个变体。缺货 OUT=${counts.OUT}，偏低 LOW=${counts.LOW}，正常 OK=${counts.OK}，无销量 NO_SALES=${counts.NO_SALES}，未追踪 NOT_TRACKED=${counts.NOT_TRACKED}。` +
    `补货点 ≈ ceil(近${cfg.lookbackDaysLong || 30}天日均销量 × ${cfg.safetyDays || 14}天安全库存)` +
    (Number(cfg.lowStockExtraUnits) ? ` + ${cfg.lowStockExtraUnits} 件缓冲` : '') + '。';
  if (top.length) {
    const topZh = reorder.slice(0, 5).map(r => {
      const name = `${r.product_title}${r.variant_title && r.variant_title !== 'Default Title' ? ' / ' + r.variant_title : ''}`;
      return `${name}（sku ${r.sku || '—'}）：库存 ${r.inventory_quantity}，建议补 ${r.suggested_order_qty}，状态 ${r.status}`;
    });
    text_zh += '优先补货：' + topZh.join('；') + '。';
  } else text_zh += '目前没有需要补货的商品。';

  const summary = lang === 'zh' ? text_zh : text_en;
  return { counts, text_en, text_zh, summary, top_reorder: top };
}

function computeAll(input) {
  const cfg = input._cfg || input.cfg || {};
  const variants = input.variants || [];
  const rows = variants.map(v => computeOne(v, cfg));
  const summary = buildSummary(rows, cfg);
  return { rows, summary, _cfg: cfg };
}

if (typeof module !== 'undefined' && module.exports) {
  module.exports = { computeOne, computeAll, buildSummary, ceil };
}

const item = $input.first().json;
const out = computeAll(item);
return [{ json: out }];

const d = $input.first().json, at = $now.toFormat('yyyy-LL-dd HH:mm');
const rows = (d.rows || []).map(r => ({ ...r, generated_at: at, source: d._cfg ? undefined : undefined }));
const tagged = (d.rows || []).map(r => ({ ...r, generated_at: at }));
return (tagged.length ? tagged : [{ product_title: '', note: 'No variants', generated_at: at }]).map(json => ({ json }));

const d = $input.first().json, at = $now.toFormat('yyyy-LL-dd HH:mm');
const s = d.summary || {}, c = s.counts || {};
const rows = [
  { generated_at: at, type: 'summary', language: 'en', item: 'summary_en', detail: s.text_en || s.summary || '' },
  { generated_at: at, type: 'summary', language: 'zh', item: 'summary_zh', detail: s.text_zh || '' },
  { generated_at: at, type: 'counts', language: '', item: 'OUT', detail: String(c.OUT || 0) },
  { generated_at: at, type: 'counts', language: '', item: 'LOW', detail: String(c.LOW || 0) },
  { generated_at: at, type: 'counts', language: '', item: 'OK', detail: String(c.OK || 0) },
  { generated_at: at, type: 'counts', language: '', item: 'NO_SALES', detail: String(c.NO_SALES || 0) },
  { generated_at: at, type: 'counts', language: '', item: 'NOT_TRACKED', detail: String(c.NOT_TRACKED || 0) },
];
if (d.shopify_error) rows.push({ generated_at: at, type: 'check', language: '', item: 'SHOPIFY_ERROR', detail: String(d.shopify_error).slice(0, 200) });
const primary = ((d._cfg || {}).summaryLanguage || 'en').toLowerCase() === 'zh' ? (s.text_zh || '') : (s.text_en || s.summary || '');
rows.unshift({ generated_at: at, type: 'summary', language: (d._cfg || {}).summaryLanguage || 'en', item: 'summary', detail: primary });
return rows.map(json => ({ json }));
